 40	func newDispatcher(sender Sender) (*Dispatcher, *clock.Fake) {
 41		clk := clock.NewFake(time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC))
 42		eps := StaticEndpoints{"m_1": {URL: "https://merchant.example/hooks", Secret: "s3cret"}}
 43		return NewDispatcher(sender, eps, clk, Policy{MaxAttempts: 4, BaseDelay: time.Second, MaxDelay: time.Minute}), clk
 44	}
