 46	func publishOne(t *testing.T, d *Dispatcher, merchant string) {
 47		t.Helper()
 48		p := payment.Payment{ID: "pay_1", MerchantID: merchant, Amount: money.MustNew(1000, "USD"), Status: payment.StatusSucceeded}
 49		if err := d.Publish(context.Background(), payment.Event{Type: "payment.succeeded", Payment: p}); err != nil {
 50			t.Fatal(err)
 51		}
 52	}
