122	func TestNoEndpointIsDropped(t *testing.T) {
123		s := &scriptedSender{}
124		d, _ := newDispatcher(s)
125		publishOne(t, d, "m_unknown")
126		if err := d.Flush(context.Background()); err != nil {
127			t.Fatal(err)
128		}
129		if len(s.calls) != 0 || len(d.DeadLetters()) != 0 {
130			t.Fatalf("calls %d dead %d", len(s.calls), len(d.DeadLetters()))
131		}
132	}
