134	func TestHTTPSender(t *testing.T) {
135		var gotSig string
136		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
137			gotSig = r.Header.Get(SignatureHeader)
138			w.WriteHeader(http.StatusAccepted)
139		}))
140		defer srv.Close()
141		status, err := HTTPSender{Client: srv.Client()}.Send(context.Background(), Delivery{URL: srv.URL, Body: []byte("{}"), Headers: map[string]string{SignatureHeader: "t=1,v1=00"}})
142		if err != nil || status != http.StatusAccepted || gotSig != "t=1,v1=00" {
143			t.Fatalf("status %d err %v sig %q", status, err, gotSig)
144		}
145	}

