// Flush delivers every queued event. It returns early only if ctx is done;
// undelivered events stay queued in that case.
func (d *Dispatcher) Flush(ctx context.Context) error {
	d.mu.Lock()
	batch := d.queue
	d.queue = nil
	d.mu.Unlock()

	for i, ev := range batch {
		if _, err := d.deliver(ctx, ev); err != nil {
			d.mu.Lock()
			d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
			d.mu.Unlock()
			return fmt.Errorf("flush webhooks: %w", err)
		}
	}
	return nil
}

// Replay removes eventID from the dead-letter list and delivers it again with
// the normal retry policy, preserving the event ID and payload.
func (d *Dispatcher) Replay(ctx context.Context, eventID string) (delivered bool, err error) {
	d.mu.Lock()
	idx := slices.IndexFunc(d.dead, func(dl DeadLetter) bool {
		return dl.Event.ID == eventID
	})
	if idx < 0 {
		d.mu.Unlock()
		return false, fmt.Errorf("replay %s: %w", eventID, ErrDeadLetterNotFound)
	}
	dl := d.dead[idx]
	d.dead = slices.Delete(d.dead, idx, idx+1)
	d.mu.Unlock()

	ok, err := d.deliver(ctx, dl.Event)
	if err != nil {
		d.mu.Lock()
		d.dead = append(d.dead, dl)
		d.mu.Unlock()
		return false, fmt.Errorf("replay %s: %w", eventID, err)
	}
	return ok, nil
}

// deliver attempts ev until success, a permanent failure or MaxAttempts.
// It only returns an error when ctx is done.
func (d *Dispatcher) deliver(ctx context.Context, ev Event) (bool, error) {
	if err := ctx.Err(); err != nil {
		return false, err
	}
	ep, ok := d.endpoints.Endpoint(ev.MerchantID)
	if !ok {
		return false, nil // merchant has no webhook configured
	}
	body, err := json.Marshal(ev)
	if err != nil {
		d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
		return false, nil
	}
	var (
		status  int
		sendErr error
		attempt int
	)
	for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
		headers := map[string]string{
			"Content-Type":  "application/json",
			"Webhook-Id":    ev.ID,
			SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
		}
		status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
		if sendErr == nil && status >= 200 && status < 300 {
			d.mu.Lock()
			d.delivered++
			d.mu.Unlock()
			return true, nil
		}
		if err := ctx.Err(); err != nil {
			return false, err
		}
		if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
			break
		}
		if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
			return false, err
		}
	}
	d.deadLetter(ev, attempt, status, sendErr)
	return false, nil
}

