func TestReplayDelivered(t *testing.T) {
	ctx := context.Background()
	// Initial delivery fails permanently (404); replay retries once on 503 then succeeds (200).
	s := &scriptedSender{statuses: []int{http.StatusNotFound, http.StatusServiceUnavailable, http.StatusOK}}
	d, clk := newDispatcher(s)
	publishOne(t, d, "m_1")
	if err := d.Flush(ctx); err != nil {
		t.Fatal(err)
	}
	dead := d.DeadLetters()
	if len(dead) != 1 || d.Delivered() != 0 {
		t.Fatalf("dead=%d delivered=%d", len(dead), d.Delivered())
	}
	evID := dead[0].Event.ID
	origCall := s.calls[0]

	clk.Advance(30 * time.Minute)
	delivered, err := d.Replay(ctx, evID)
	if err != nil || !delivered {
		t.Fatalf("Replay = (%v, %v), want (true, nil)", delivered, err)
	}
	if len(d.DeadLetters()) != 0 || d.Delivered() != 1 {
		t.Fatalf("after replay: dead=%d delivered=%d", len(d.DeadLetters()), d.Delivered())
	}
	if len(s.calls) != 3 {
		t.Fatalf("calls = %d, want 3", len(s.calls))
	}
	lastCall := s.calls[2]
	if lastCall.EventID != evID || lastCall.Headers["Webhook-Id"] != evID {
		t.Fatalf("event id mismatch: %+v", lastCall)
	}
	if !bytes.Equal(lastCall.Body, origCall.Body) {
		t.Fatalf("payload changed:\ngot:  %s\nwant: %s", lastCall.Body, origCall.Body)
	}
	if lastCall.Headers[SignatureHeader] == origCall.Headers[SignatureHeader] {
		t.Fatalf("signature was not recomputed")
	}
	if err := Verify("s3cret", lastCall.Headers[SignatureHeader], lastCall.Body, clk.Now(), time.Minute); err != nil {
		t.Fatalf("replayed signature invalid at send time: %v", err)
	}

	// Replaying again after successful delivery returns ErrDeadLetterNotFound.
	if _, err := d.Replay(ctx, evID); !errors.Is(err, ErrDeadLetterNotFound) {
		t.Fatalf("second Replay err = %v, want ErrDeadLetterNotFound", err)
	}
}

func TestReplayFailsAgainUpdatesDeadLetterOnce(t *testing.T) {
	ctx := context.Background()
	boom := errors.New("dial tcp: refused")
	// Event 1: 4 network failures -> dead-lettered (attempts=4, status=0, err=boom).
	// Event 2: 1 permanent 404 -> dead-lettered.
	// Replay of Event 1: permanent 410 -> dead-lettered once (attempts=1, status=410, err="").
	s := &scriptedSender{
		statuses: []int{0, 0, 0, 0, http.StatusNotFound, http.StatusGone},
		errs:     []error{boom, boom, boom, boom, nil, nil},
	}
	d, clk := newDispatcher(s)
	publishOne(t, d, "m_1")
	publishOne(t, d, "m_1")
	if err := d.Flush(ctx); err != nil {
		t.Fatal(err)
	}
	before := d.DeadLetters()
	if len(before) != 2 {
		t.Fatalf("initial dead = %d, want 2", len(before))
	}
	firstID, secondID := before[0].Event.ID, before[1].Event.ID
	if before[0].Attempts != 4 || before[0].LastError == "" {
		t.Fatalf("unexpected initial dead letter: %+v", before[0])
	}

	clk.Advance(10 * time.Minute)
	replayTime := clk.Now()
	delivered, err := d.Replay(ctx, firstID)
	if err != nil || delivered {
		t.Fatalf("Replay = (%v, %v), want (false, nil)", delivered, err)
	}
	after := d.DeadLetters()
	if len(after) != 2 {
		t.Fatalf("dead letters = %d, want 2: %+v", len(after), after)
	}
	var gotFirst, gotSecond []DeadLetter
	for _, dl := range after {
		switch dl.Event.ID {
		case firstID:
			gotFirst = append(gotFirst, dl)
		case secondID:
			gotSecond = append(gotSecond, dl)
		}
	}
	if len(gotFirst) != 1 || len(gotSecond) != 1 {
		t.Fatalf("counts first=%d second=%d", len(gotFirst), len(gotSecond))
	}
	dl := gotFirst[0]
	if dl.Attempts != 1 || dl.LastStatus != http.StatusGone || dl.LastError != "" || !dl.FailedAt.Equal(replayTime) {
		t.Fatalf("updated dead letter = %+v", dl)
	}
}

func TestReplayUnknownEventID(t *testing.T) {
	s := &scriptedSender{}
