func TestReplayDeadLetter(t *testing.T) {
	clk := clock.NewFake(time.Date(2026, 4, 1, 9, 0, 0, 0, time.UTC))
	sender := &statusSender{}
	sender.status.Store(http.StatusBadRequest)
	eps := webhook.StaticEndpoints{"m_1": {URL: "https://merchant.example/hooks", Secret: "sec"}}
	hooks := webhook.NewDispatcher(sender, eps, clk, webhook.Policy{MaxAttempts: 2, BaseDelay: time.Second, MaxDelay: time.Minute})
	svc := payment.NewService(store.NewMemory(), clk, payment.NewSeqIDs(), hooks, payment.Config{FeeBps: 290})
	a := &testAPI{t: t, srv: NewServer(svc, idempotency.NewMemory(clk, 24*time.Hour), hooks), clk: clk, hooks: hooks}

	// Unknown event id -> 404 not_found.
	notFound := a.do("POST", "/webhooks/dead-letters/evt_unknown/replay", "")
	if notFound.Code != http.StatusNotFound {
		t.Fatalf("unknown status = %d: %s", notFound.Code, notFound.Body)
	}
	if e := decode[errorBody](t, notFound); e.Error.Code != "not_found" {
		t.Fatalf("unknown error code = %q, want not_found", e.Error.Code)
	}

	// Create a payment so an event is published, then flush to dead-letter it.
	if rec := a.do("POST", "/payments", `{"merchant_id":"m_1","amount":"10.00","currency":"USD"}`); rec.Code != http.StatusCreated {
		t.Fatalf("create: %d %s", rec.Code, rec.Body)
	}
	if err := hooks.Flush(context.Background()); err != nil {
		t.Fatal(err)
	}

	listRec := a.do("GET", "/webhooks/dead-letters", "")
	var listed struct {
		Data []deadLetterResponse `json:"data"`
	}
	listed = decode[struct {
		Data []deadLetterResponse `json:"data"`
	}](t, listRec)
	if len(listed.Data) != 1 {
		t.Fatalf("dead letters = %d, want 1", len(listed.Data))
	}
	evID := listed.Data[0].EventID

	// Replay while endpoint still fails (503 x2) -> 200 {"event_id":..., "delivered": false}.
	sender.status.Store(http.StatusServiceUnavailable)
	failRec := a.do("POST", "/webhooks/dead-letters/"+evID+"/replay", "")
	if failRec.Code != http.StatusOK {
		t.Fatalf("failed replay status = %d: %s", failRec.Code, failRec.Body)
	}
	wantFailJSON := `{"event_id":"` + evID + `","delivered":false}` + "\n"
	if failRec.Body.String() != wantFailJSON {
		t.Fatalf("failed replay body = %q, want %q", failRec.Body.String(), wantFailJSON)
	}
	listed = decode[struct {
		Data []deadLetterResponse `json:"data"`
	}](t, a.do("GET", "/webhooks/dead-letters", ""))
	if len(listed.Data) != 1 || listed.Data[0].Attempts != 2 || listed.Data[0].LastStatus != http.StatusServiceUnavailable {
		t.Fatalf("dead letters after failed replay = %+v", listed.Data)
	}

	// Merchant fixes endpoint -> 200 {"event_id":..., "delivered": true}, dead-letter removed.
	sender.status.Store(http.StatusOK)
	okRec := a.do("POST", "/webhooks/dead-letters/"+evID+"/replay", "")
	if okRec.Code != http.StatusOK {
		t.Fatalf("ok replay status = %d: %s", okRec.Code, okRec.Body)
	}
	wantOKJSON := `{"event_id":"` + evID + `","delivered":true}` + "\n"
	if okRec.Body.String() != wantOKJSON {
		t.Fatalf("ok replay body = %q, want %q", okRec.Body.String(), wantOKJSON)
	}
	if rec := a.do("GET", "/webhooks/dead-letters", ""); rec.Body.String() != "{\"data\":[]}\n" {
		t.Fatalf("dead letters after ok replay = %q", rec.Body.String())
	}

	// Replaying again after delivery -> 404 not_found.
	againRec := a.do("POST", "/webhooks/dead-letters/"+evID+"/replay", "")
	if againRec.Code != http.StatusNotFound {
		t.Fatalf("replay after delivery status = %d: %s", againRec.Code, againRec.Body)
	}
}

