	if failRec.Body.String() != wantFailJSON {
		t.Fatalf("failed replay body = %q, want %q", failRec.Body.String(), wantFailJSON)
	}
	listed = decode[struct {
		Data []deadLetterResponse `json:"data"`
	}](t, a.do("GET", "/webhooks/dead-letters", ""))
	if len(listed.Data) != 1 || listed.Data[0].Attempts != 2 || listed.Data[0].LastStatus != http.StatusServiceUnavailable {
		t.Fatalf("dead letters after failed replay = %+v", listed.Data)
	}

	// Merchant fixes endpoint -> 200 {"event_id":..., "delivered": true}, dead-letter removed.
	sender.status.Store(http.StatusOK)
	okRec := a.do("POST", "/webhooks/dead-letters/"+evID+"/replay", "")
	if okRec.Code != http.StatusOK {
		t.Fatalf("ok replay status = %d: %s", okRec.Code, okRec.Body)
	}
	wantOKJSON := `{"event_id":"` + evID + `","delivered":true}` + "\n"
	if okRec.Body.String() != wantOKJSON {
		t.Fatalf("ok replay body = %q, want %q", okRec.Body.String(), wantOKJSON)
	}
	if rec := a.do("GET", "/webhooks/dead-letters", ""); rec.Body.String() != "{\"data\":[]}\n" {
		t.Fatalf("dead letters after ok replay = %q", rec.Body.String())
	}

	// Replaying again after delivery -> 404 not_found.
	againRec := a.do("POST", "/webhooks/dead-letters/"+evID+"/replay", "")
	if againRec.Code != http.StatusNotFound {
		t.Fatalf("replay after delivery status = %d: %s", againRec.Code, againRec.Body)
	}
}

