  1	// Package webhook delivers payment events to merchant endpoints with signed
  2	// payloads, retries with exponential backoff and a dead-letter list.
  3	package webhook
  4	
  5	import (
  6		"context"
  7		"encoding/json"
  8		"errors"
  9		"fmt"
 10		"net/http"
 11		"slices"
 12		"sync"
 13		"time"
 14	
 15		"example.com/gopayments/clock"
 16		"example.com/gopayments/payment"
 17	)
 18	
 19	// ErrDeadLetterNotFound is returned when replaying an event that is not in the dead-letter list.
 20	var ErrDeadLetterNotFound = errors.New("dead-letter event not found")
 21	
 22	// Event is the webhook payload.
 23	type Event struct {
 24		ID         string          `json:"id"`
 25		Type       string          `json:"type"`
 26		MerchantID string          `json:"merchant_id"`
 27		CreatedAt  time.Time       `json:"created_at"`
 28		Data       json.RawMessage `json:"data"`
 29	}
 30	
 31	// Endpoint is a merchant's webhook destination.
 32	type Endpoint struct {
 33		URL    string
 34		Secret string
 35	}
 36	
 37	// Endpoints resolves the endpoint of a merchant.
 38	type Endpoints interface {
 39		Endpoint(merchantID string) (Endpoint, bool)
 40	}
 41	
 42	// StaticEndpoints is a fixed merchant -> endpoint map.
 43	type StaticEndpoints map[string]Endpoint
 44	
 45	// Endpoint implements Endpoints.
 46	func (s StaticEndpoints) Endpoint(merchantID string) (Endpoint, bool) {
 47		e, ok := s[merchantID]
 48		return e, ok
 49	}
 50	
 51	// Policy controls retries.
 52	type Policy struct {
 53		MaxAttempts int
 54		BaseDelay   time.Duration
 55		MaxDelay    time.Duration
 56	}
 57	
 58	// DefaultPolicy is the production retry policy.
 59	func DefaultPolicy() Policy {
 60		return Policy{MaxAttempts: 6, BaseDelay: time.Second, MaxDelay: 10 * time.Minute}
 61	}
 62	
 63	// Backoff is the wait after failed attempt n (n >= 1): BaseDelay * 2^(n-1),
 64	// capped at MaxDelay.
 65	func (p Policy) Backoff(n int) time.Duration {
 66		d := p.BaseDelay
 67		for i := 1; i < n; i++ {
 68			if d >= p.MaxDelay/2 {
 69				return p.MaxDelay
 70			}
 71			d *= 2
 72		}
 73		return min(d, p.MaxDelay)
 74	}
 75	
 76	// DeadLetter is an event that exhausted its retries or failed permanently.
 77	type DeadLetter struct {
 78		Event      Event
 79		Attempts   int
 80		LastStatus int
 81		LastError  string
 82		FailedAt   time.Time
 83	}
 84	
 85	// Dispatcher queues events and delivers them.
 86	type Dispatcher struct {
 87		sender    Sender
 88		endpoints Endpoints
 89		clock     clock.Clock
 90		policy    Policy
 91	
 92		mu        sync.Mutex
 93		seq       int
 94		queue     []Event
 95		dead      []DeadLetter
 96		delivered int
 97	}
 98	
 99	var _ payment.Publisher = (*Dispatcher)(nil)
100	
101	// NewDispatcher wires a dispatcher.
102	func NewDispatcher(sender Sender, endpoints Endpoints, clk clock.Clock, policy Policy) *Dispatcher {
103		return &Dispatcher{sender: sender, endpoints: endpoints, clock: clk, policy: policy}
104	}
105	
106	type paymentData struct {
107		PaymentID string `json:"payment_id"`
108		Status    string `json:"status"`
109		Amount    string `json:"amount"`
110		Currency  string `json:"currency"`
111		Refunded  string `json:"refunded_amount"`
112		RefundID  string `json:"refund_id,omitempty"`
113	}
114	
115	// Publish implements payment.Publisher by queueing a webhook event.
116	func (d *Dispatcher) Publish(_ context.Context, ev payment.Event) error {
117		data := paymentData{
118			PaymentID: ev.Payment.ID,
119			Status:    string(ev.Payment.Status),
120			Amount:    ev.Payment.Amount.Decimal(),
121			Currency:  ev.Payment.Amount.Currency.Code,
122			Refunded:  ev.Payment.RefundedAmount().Decimal(),
123		}
124		if ev.Refund != nil {
125			data.RefundID = ev.Refund.ID
126		}
127		raw, err := json.Marshal(data)
128		if err != nil {
129			return fmt.Errorf("encode %s event: %w", ev.Type, err)
130		}
131		d.mu.Lock()
132		defer d.mu.Unlock()
133		d.seq++
134		d.queue = append(d.queue, Event{
135			ID:         fmt.Sprintf("evt_%06d", d.seq),
136			Type:       ev.Type,
137			MerchantID: ev.Payment.MerchantID,
138			CreatedAt:  d.clock.Now(),
139			Data:       raw,
140		})
141		return nil
142	}
143	
144	// Pending returns the number of queued, undelivered events.
145	func (d *Dispatcher) Pending() int {
146		d.mu.Lock()
147		defer d.mu.Unlock()
148		return len(d.queue)
149	}
150	
151	// Delivered returns how many events were delivered successfully.
152	func (d *Dispatcher) Delivered() int {
153		d.mu.Lock()
154		defer d.mu.Unlock()
155		return d.delivered
156	}
157	
158	// DeadLetters returns a snapshot of the dead-letter list.
159	func (d *Dispatcher) DeadLetters() []DeadLetter {
160		d.mu.Lock()
161		defer d.mu.Unlock()
162		return append([]DeadLetter(nil), d.dead...)
163	}
164	
165	// Flush delivers every queued event. It returns early only if ctx is done;
166	// undelivered events stay queued in that case.
167	func (d *Dispatcher) Flush(ctx context.Context) error {
168		d.mu.Lock()
169		batch := d.queue
170		d.queue = nil
171		d.mu.Unlock()
172	
173		for i, ev := range batch {
174			if _, err := d.deliver(ctx, ev); err != nil {
175				d.mu.Lock()
176				d.queue = append(append([]Event(nil), batch[i:]...), d.queue...)
177				d.mu.Unlock()
178				return fmt.Errorf("flush webhooks: %w", err)
179			}
180		}
181		return nil
182	}
183	
184	// Replay removes eventID from the dead-letter list and delivers it again with
185	// the normal retry policy, preserving the event ID and payload.
186	func (d *Dispatcher) Replay(ctx context.Context, eventID string) (delivered bool, err error) {
187		d.mu.Lock()
188		idx := slices.IndexFunc(d.dead, func(dl DeadLetter) bool {
189			return dl.Event.ID == eventID
190		})
191		if idx < 0 {
192			d.mu.Unlock()
193			return false, fmt.Errorf("replay %s: %w", eventID, ErrDeadLetterNotFound)
194		}
195		dl := d.dead[idx]
196		d.dead = slices.Delete(d.dead, idx, idx+1)
197		d.mu.Unlock()
198	
199		ok, err := d.deliver(ctx, dl.Event)
200		if err != nil {
201			d.mu.Lock()
202			d.dead = append(d.dead, dl)
203			d.mu.Unlock()
204			return false, fmt.Errorf("replay %s: %w", eventID, err)
205		}
206		return ok, nil
207	}
208	
209	// deliver attempts ev until success, a permanent failure or MaxAttempts.
210	// It only returns an error when ctx is done.
211	func (d *Dispatcher) deliver(ctx context.Context, ev Event) (bool, error) {
212		if err := ctx.Err(); err != nil {
213			return false, err
214		}
215		ep, ok := d.endpoints.Endpoint(ev.MerchantID)
216		if !ok {
217			return false, nil // merchant has no webhook configured
218		}
219		body, err := json.Marshal(ev)
220		if err != nil {
221			d.deadLetter(ev, 0, 0, fmt.Errorf("encode event: %w", err))
222			return false, nil
223		}
224		var (
225			status  int
226			sendErr error
227			attempt int
228		)
229		for attempt = 1; attempt <= d.policy.MaxAttempts; attempt++ {
230			headers := map[string]string{
231				"Content-Type":  "application/json",
232				"Webhook-Id":    ev.ID,
233				SignatureHeader: Sign(ep.Secret, d.clock.Now().Unix(), body),
234			}
235			status, sendErr = d.sender.Send(ctx, Delivery{EventID: ev.ID, URL: ep.URL, Body: body, Headers: headers, Attempt: attempt})
236			if sendErr == nil && status >= 200 && status < 300 {
237				d.mu.Lock()
238				d.delivered++
239				d.mu.Unlock()
240				return true, nil
241			}
242			if err := ctx.Err(); err != nil {
243				return false, err
244			}
245			if !retryable(status, sendErr) || attempt == d.policy.MaxAttempts {
246				break
247			}
248			if err := d.clock.Sleep(ctx, d.policy.Backoff(attempt)); err != nil {
249				return false, err
250			}
251		}
252		d.deadLetter(ev, attempt, status, sendErr)
253		return false, nil
254	}
255	
256	func (d *Dispatcher) deadLetter(ev Event, attempts, status int, err error) {
257		dl := DeadLetter{Event: ev, Attempts: attempts, LastStatus: status, FailedAt: d.clock.Now()}
258		if err != nil {
259			dl.LastError = err.Error()
260		}
261		d.mu.Lock()
262		defer d.mu.Unlock()
263		d.dead = append(d.dead, dl)
264	}
265	
266	// retryable reports whether a failed attempt should be retried: transport
267	// errors, 408, 429 and 5xx are transient; any other status is permanent.
268	func retryable(status int, err error) bool {
269		if err != nil {
270			return true
271		}
272		return status == http.StatusRequestTimeout || status == http.StatusTooManyRequests || status >= 500
273	}

  1	package api
  2	
  3	import (
